113,U+2C60-2C7F,U+A720-A7FF;font-display:swap;}@font-face {font-family:'Space Mono';font-style:normal;font-weight:400;src:url(/cf-fonts/s/space-mono/5.2.9/vietnamese/400/normal.woff2);unicode-range:U+0102-0103,U+0110-0111,U+0128-0129,U+0168-0169,U+01A0-01A1,U+01AF-01B0,U+0300-0301,U+0303-0304,U+0308-0309,U+0323,U+0329,U+1EA0-1EF9,U+20AB;font-display:swap;}@font-face {font-family:'Space Mono';font-style:normal;font-weight:700;src:url(/cf-fonts/s/space-mono/5.2.9/vietnamese/700/normal.woff2);unicode-range:U+0102-0103,U+0110-0111,U+0128-0129,U+0168-0169,U+01A0-01A1,U+01AF-01B0,U+0300-0301,U+0303-0304,U+0308-0309,U+0323,U+0329,U+1EA0-1EF9,U+20AB;font-display:swap;}@font-face {font-family:'Space Mono';font-style:normal;font-weight:700;src:url(/cf-fonts/s/space-mono/5.2.9/latin/700/normal.woff2);unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD;font-display:swap;}@font-face {font-family:'Space Mono';font-style:normal;font-weight:700;src:url(/cf-fonts/s/space-mono/5.2.9/latin-ext/700/normal.woff2);unicode-range:U+0100-02BA,U+02BD-02C5,U+02C7-02CC,U+02CE-02D7,U+02DD-02FF,U+0304,U+0308,U+0329,U+1D00-1DBF,U+1E00-1E9F,U+1EF2-1EFF,U+2020,U+20A0-20AB,U+20AD-20C0,U+2113,U+2C60-2C7F,U+A720-A7FF;font-display:swap;}</style>
    <style>
        :root {
            --purple: #7C3AED;
            --purple-dark: #6423D6;
            --purple-100: #EDE4FF;
            --purple-50: #F8F5FF;
            --ink: #14172A;
            --muted: #6B7280;
            --border: #E7E1F7;
        }

        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: 'Inter', sans-serif;
            background: #fff;
            color: var(--ink);
            -webkit-font-smoothing: antialiased;
        }

        .hero {
            position: relative;
            overflow: hidden;
            max-width: 1360px;
            margin: 0 auto;
            padding: 100px 56px;
        }

        .bg-grid {
            position: absolute;
            inset: 0;
            background-image: radial-gradient(circle, rgba(124, 58, 237, 0.12) 1.4px, transparent 1.4px);
            background-size: 28px 28px;
            -webkit-mask-image: linear-gradient(to bottom, black, transparent 80%);
            mask-image: linear-gradient(to bottom, black, transparent 80%);
            pointer-events: none;
        }

        .hero-inner {
            position: relative;
            display: grid;
            grid-template-columns: 1.05fr 0.95fr;
            gap: 48px;
            align-items: center;
        }

        .eyebrow {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            font-family: 'Space Mono', monospace;
            font-size: 11.5px;
            font-weight: 700;
            letter-spacing: .12em;
            text-transform: uppercase;
            color: var(--purple-dark);
            background: var(--purple-50);
            border: 1px solid var(--purple-100);
            padding: 7px 14px 7px 11px;
            border-radius: 999px;
            margin-bottom: 28px;
        }

        .eyebrow .dot {
            width: 7px;
            height: 7px;
            border-radius: 50%;
            background: var(--purple);
            animation: pulse 1.8s infinite;
        }

        @keyframes pulse {
            0% {
                box-shadow: 0 0 0 0 rgba(124, 58, 237, .45);
            }

            70% {
                box-shadow: 0 0 0 7px rgba(124, 58, 237, 0);
            }

            100% {
                box-shadow: 0 0 0 0 rgba(124, 58, 237, 0);
            }
        }

        .headline {
            font-family: 'Space Grotesk', sans-serif;
            font-weight: 700;
            font-size: clamp(38px, 5.2vw, 68px);
            line-height: 0.98;
            letter-spacing: -0.01em;
        }

        .headline .line-1 {
            display: block;
            color: var(--ink);
        }

        .headline .line-2 {
            position: relative;
            display: inline-block;
            color: var(--purple);
            margin-top: 2px;
        }

        .headline .line-2::before {
            content: "";
            position: absolute;
            left: -6px;
            right: -10px;
            bottom: 8px;
            height: 0.30em;
            background: var(--purple-100);
            z-index: -1;
            transform: skewX(-6deg);
        }

        .subhead {
            margin-top: 26px;
            font-size: 17px;
            line-height: 1.65;
            color: var(--muted);
            max-width: 460px;
        }

        .cta-row {
            display: flex;
            gap: 14px;
            margin-top: 34px;
            flex-wrap: wrap;
        }

        .btn {
            font-family: 'Inter';
            font-weight: 600;
            font-size: 15px;
            padding: 15px 26px;
            border-radius: 12px;
            cursor: pointer;
            display: inline-flex;
            align-items: center;
            gap: 8px;
            border: 1.5px solid transparent;
            transition: transform .18s ease, box-shadow .18s ease, background .18s ease;
        }

        .btn:focus-visible {
            outline: 2px solid var(--purple-dark);
            outline-offset: 3px;
        }

        .btn-primary {
            background: linear-gradient(135deg, var(--purple), var(--purple-dark));
            color: #fff;
            box-shadow: 0 10px 24px -8px rgba(124, 58, 237, .55);
        }

        .btn-primary:hover {
            transform: translateY(-2px);
            box-shadow: 0 14px 28px -8px rgba(124, 58, 237, .6);
        }

        .btn-secondary {
            background: transparent;
            color: var(--purple);
            border-color: var(--border);
        }

        .btn-secondary:hover {
            background: var(--purple-50);
            border-color: var(--purple-100);
        }

        .btn svg {
            width: 16px;
            height: 16px;
        }

        .scoreboard {
            margin-top: 46px;
            display: flex;
            align-items: center;
            background: linear-gradient(180deg, var(--ink), #0E1022);
            border-radius: 16px;
            padding: 20px 26px;
            position: relative;
            max-width: 480px;
            box-shadow: 0 18px 40px -20px rgba(20, 23, 42, .45);
        }

        .scoreboard::before {
            content: "";
            position: absolute;
            top: 0;
            left: 18px;
            right: 18px;
            height: 2px;
            background: linear-gradient(90deg, transparent, var(--purple), transparent);
        }

        .stat {
            flex: 1;
            text-align: left;
        }

        .stat-num {
            display: flex;
            align-items: center;
            gap: 6px;
            font-family: 'Space Mono', monospace;
            font-weight: 700;
            font-size: 20px;
            color: #fff;
        }

        .stat-label {
            display: block;
            margin-top: 4px;
            font-size: 11px;
            color: #A8A8C0;
        }

        .live-dot {
            width: 6px;
            height: 6px;
            border-radius: 50%;
            background: #4ADE80;
            animation: pulse-green 1.6s infinite;
        }

        @keyframes pulse-green {
            0% {
                box-shadow: 0 0 0 0 rgba(74, 222, 128, .55);
            }

            70% {
                box-shadow: 0 0 0 6px rgba(74, 222, 128, 0);
            }

            100% {
                box-shadow: 0 0 0 0 rgba(74, 222, 128, 0);
            }
        }

        .divider {
            width: 1px;
            height: 34px;
            background: rgba(255, 255, 255, .12);
            margin: 0 16px;
        }

        .hero-visual {
            position: relative;
            height: 440px;
        }

        .glow {
            position: absolute;
            left: 50%;
            top: 50%;
            width: 380px;
            height: 380px;
            transform: translate(-50%, -50%);
            background: radial-gradient(circle, rgba(124, 58, 237, .22), transparent 70%);
            filter: blur(8px);
        }

        .game-tile {
            position: absolute;
            width: 124px;
            height: 144px;
            background: #fff;
            border: 1px solid var(--border);
            border-radius: 18px;
            box-shadow: 0 16px 30px -14px rgba(20, 10, 60, .18);
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            gap: 10px;
        }

        .tile-icon {
            width: 44px;
            height: 44px;
            border-radius: 12px;
            display: flex;
            align-items: center;
            justify-content: center;
            background: var(--purple-50);
            color: var(--purple);
        }

        .tile-label {
            font-size: 12px;
            font-weight: 600;
            color: var(--ink);
        }

        .tile-dice {
            left: 4%;
            top: 5%;
            transform: rotate(-11deg);
        }

        .tile-cards {
            right: 0%;
            top: 0%;
            transform: rotate(9deg);
        }

        .leaderboard {
            position: absolute;
            left: 50%;
            top: 56%;
            transform: translate(-50%, -50%) rotate(-2deg);
            width: 276px;
            background: #fff;
            border: 1px solid var(--border);
            border-radius: 20px;
            box-shadow: 0 30px 50px -20px rgba(20, 10, 60, .28);
            padding: 20px 22px;
        }

        .lb-head {
            display: flex;
            align-items: center;
            justify-content: space-between;
            margin-bottom: 16px;
        }

        .lb-title {
            font-family: 'Space Grotesk';
            font-weight: 700;
            font-size: 14.5px;
        }

        .lb-live {
            display: flex;
            align-items: center;
            gap: 5px;
            font-family: 'Space Mono';
            font-size: 10px;
            font-weight: 700;
            letter-spacing: .06em;
            color: #16A34A;
            background: #F0FDF4;
            padding: 4px 8px;
            border-radius: 999px;
        }

        .lb-live .live-dot {
            background: #16A34A;
        }

        .lb-row {
            display: flex;
            align-items: center;
            gap: 10px;
            padding: 7px 0;
        }

        .lb-rank {
            font-family: 'Space Mono';
            font-weight: 700;
            font-size: 12px;
            color: var(--muted);
            width: 16px;
        }

        .lb-avatar {
            width: 24px;
            height: 24px;
            border-radius: 50%;
            flex-shrink: 0;
        }

        .lb-bar-wrap {
            flex: 1;
            height: 6px;
            background: #F1ECFB;
            border-radius: 4px;
            overflow: hidden;
        }

        .lb-bar {
            height: 100%;
            background: linear-gradient(90deg, var(--purple), var(--purple-dark));
            border-radius: 4px;
        }

        .lb-score {
            font-family: 'Space Mono';
            font-size: 11.5px;
            font-weight: 700;
            color: var(--ink);
        }

        .badge-tag {
            position: absolute;
            right: 6%;
            bottom: 6%;
            background: var(--ink);
            color: #fff;
            font-family: 'Space Mono';
            font-weight: 700;
            font-size: 12px;
            padding: 9px 14px;
            border-radius: 10px;
            transform: rotate(-4deg);
            box-shadow: 0 14px 24px -10px rgba(20, 23, 42, .5);
        }

        @media (max-width:900px) {
            .hero {
                padding: 56px 24px;
            }

            .hero-inner {
                grid-template-columns: 1fr;
                text-align: center;
            }

            .eyebrow {
                margin-left: auto;
                margin-right: auto;
            }

            .subhead {
                margin-left: auto;
                margin-right: auto;
            }

            .cta-row {
                justify-content: center;
            }

            .scoreboard {
                max-width: 100%;
                margin-left: auto;
                margin-right: auto;
            }

            .hero-visual {
                width: 100%;
                max-width: 480px;
                margin: 40px auto 0 auto;
                height: 360px;
            }
        }

        @media (max-width:480px) {
            .hero {
                padding: 48px 16px;
            }

            .headline {
                line-height: 1.1;
            }

            .cta-row {
                flex-direction: column;
                gap: 12px;
                width: 100%;
            }

            .cta-row .btn {
                width: 100%;
                justify-content: center;
            }

            .scoreboard {
                flex-direction: column;
                align-items: stretch;
                padding: 16px 20px;
                gap: 16px;
            }

            .scoreboard .divider {
                width: 100%;
                height: 1px;
                margin: 2px 0;
            }

            .stat {
                text-align: center;
            }

            .stat-num {
                justify-content: center;
            }

            .hero-visual {
                max-width: 320px;
                height: 300px;
                margin-top: 32px;
            }

            .game-tile {
                width: 90px;
                height: 106px;
                border-radius: 14px;
            }

            .tile-icon {
                width: 34px;
                height: 34px;
            }

            .tile-label {
                font-size: 11px;
            }

            .tile-dice {
                left: -8px;
                top: 2%;
                transform: rotate(-8deg);
            }

            .tile-cards {
                right: -8px;
                top: -2%;
                transform: rotate(8deg);
            }

            .leaderboard {
                width: 200px;
                padding: 14px;
                top: 50%;
            }

            .badge-tag {
                font-size: 10px;
                padding: 6px 10px;
                right: 4%;
                bottom: 4%;
            }
        }

        @media (prefers-reduced-motion:reduce) {

            .eyebrow .dot,
            .live-dot {
                animation: none;
            }

            .btn {
                transition: none;
            }
        }
    </style>
</head>

<body>
    <section class="hero">
        <div class="bg-grid"></div>
        <div class="hero-inner">

            <div class="hero-content">
                <div class="eyebrow"><span class="dot"></span> Live Gaming Platform</div>
                <h1 class="headline">
                    <span class="line-1">New Yono</span>
                    <span class="line-2">Games</span>
                </h1>
                <p class="subhead">Explore 90+ exciting Old Yono Games. Play your favourite games and win amazing
                    rewards.</p>

                <div class="cta-row">
                    <button class="btn btn-primary" onclick="window.location.href='/all-yono-games'">
                        Play Now
                        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4"
                            stroke-linecap="round" stroke-linejoin="round">
                            <line x1="5" y1="12" x2="19" y2="12" />
                            <polyline points="12 5 19 12 12 19" />
                        </svg>
                    </button>
                    <a href="#explore" class="btn btn-secondary" style="text-decoration:none" onscroll="">Explore
                        Games</a>
                </div>

                <div class="scoreboard">
                    <div class="stat">
                        <span class="stat-num">90+</span>
                        <span class="stat-label">Old Yono Games</span>
                    </div>
                    <div class="divider"></div>
                    <div class="stat">
                        <span class="stat-num"><span class="live-dot"></span>25K+</span>
                        <span class="stat-label">Active Players</span>
                    </div>
                    <div class="divider"></div>
                    <div class="stat">
                        <span class="stat-num">125+</span>
                        <span class="stat-label">Tournaments</span>
                    </div>
                </div>
            </div>

            <div class="hero-visual">
                <div class="glow"></div>

                <div class="game-tile tile-dice">
                    <div class="tile-icon">
                        <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor"
                            stroke-width="2">
                            <rect x="3" y="3" width="18" height="18" rx="4" />
                            <circle cx="8" cy="8" r="1.2" fill="currentColor" />
                            <circle cx="16" cy="8" r="1.2" fill="currentColor" />
                            <circle cx="8" cy="16" r="1.2" fill="currentColor" />
                            <circle cx="16" cy="16" r="1.2" fill="currentColor" />
                            <circle cx="12" cy="12" r="1.2" fill="currentColor" />
                        </svg>
                    </div>
                    <span class="tile-label">Dice Games</span>
                </div>

                <div class="game-tile tile-cards">
                    <div class="tile-icon">
                        <svg width="22" height="22" viewBox="0 0 24 24" fill="currentColor">
                            <path d="M12 2c-1.7 3.4-5 6.2-5 9.4 0 2.6 2 4.6 5 4.6s5-2 5-4.6C17 8.2 13.7 5.4 12 2z" />
                            <rect x="11" y="16" width="2" height="5" />
                        </svg>
                    </div>
                    <span class="tile-label">Card Games</span>
