<style>
    @import url('https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700;800&display=swap');

    .lyg-wrapper {
        font-family: 'Outfit', sans-serif !important;
        background: #ffffff !important;
        color: #1e293b !important;
        border: 1px solid #e2e8f0 !important;
        border-radius: 16px !important;
        padding: 24px 20px !important;
        box-shadow: 0 4px 20px rgba(109, 40, 217, 0.03) !important;
        width: 100% !important;
        max-width: 800px !important;
        margin: 16px auto !important;
        box-sizing: border-box !important;
    }

    .lyg-wrapper * {
        box-sizing: border-box !important;
        font-family: 'Outfit', sans-serif !important;
    }

    /* Header styling */
    .lyg-header-box {
        text-align: center !important;
        margin-bottom: 20px !important;
        padding: 0 !important;
    }

    .lyg-title {
        font-size: 24px !important;
        font-weight: 800 !important;
        color: #0f172a !important;
        margin: 0 0 6px 0 !important;
        letter-spacing: -0.5px !important;
        line-height: 1.2 !important;
    }

    .lyg-subtitle {
        color: #475569 !important;
        font-size: 13.5px !important;
        max-width: 550px !important;
        margin: 0 auto !important;
        line-height: 1.4 !important;
    }

    /* Platform Story Card */
    .lyg-story-card {
        background: #fcfbfe !important;
        border-left: 3px solid #6d28d9 !important;
        border-radius: 4px 12px 12px 4px !important;
        padding: 16px !important;
        margin-bottom: 20px !important;
        text-align: left !important;
    }

    .lyg-story-content p {
        margin: 0 0 10px 0 !important;
        font-size: 13px !important;
        line-height: 1.5 !important;
        color: #1e293b !important;
    }

    .lyg-story-content p strong {
        color: #6d28d9 !important;
    }

    .lyg-story-content p.lyg-story-sub {
        margin-bottom: 0 !important;
        color: #475569 !important;
        font-size: 12.5px !important;
    }

    /* Space-Saving Features Tabs Section */
    .lyg-features-section {
        background: #ffffff !important;
        border: 1px solid #e2e8f0 !important;
        border-radius: 12px !important;
        padding: 16px !important;
        margin-bottom: 24px !important;
        text-align: center !important;
    }

    .lyg-features-section h3 {
        font-size: 15px !important;
        font-weight: 700 !important;
        color: #0f172a !important;
        margin: 0 0 12px 0 !important;
    }

    /* Horizontal scrollable tab buttons row */
    .lyg-tabs-nav {
        display: flex !important;
        gap: 8px !important;
        overflow-x: auto !important;
        overflow-y: hidden !important;
        padding-bottom: 6px !important;
        margin-bottom: 12px !important;
        scroll-behavior: smooth !important;
        -webkit-overflow-scrolling: touch !important;
    }

    /* Scrollbar styling for tabs */
    .lyg-tabs-nav::-webkit-scrollbar {
        height: 3px !important;
    }
    .lyg-tabs-nav::-webkit-scrollbar-track {
        background: transparent !important;
    }
    .lyg-tabs-nav::-webkit-scrollbar-thumb {
        background: rgba(109, 40, 217, 0.1) !important;
        border-radius: 4px !important;
    }

    .lyg-tab-btn {
        flex: 0 0 auto !important;
        display: inline-flex !important;
        align-items: center !important;
        background: #f8fafc !important;
        color: #475569 !important;
        border: 1px solid #e2e8f0 !important;
        padding: 6px 12px !important;
        border-radius: 8px !important;
        font-size: 12px !important;
        font-weight: 700 !important;
        cursor: pointer !important;
        transition: all 0.2s ease !important;
